import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/index.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

it('reports a thrown string with its cause and preserves the caller rejection [spec: specs/hal-engine-config-hooks/spec.md#8]', async () => {
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const errors: Error[] = [];
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Test assistant'}),
    undefined,
    {
      hooks: {
        beforeSession: async () => {
          throw 'hook failure';
        },
        onError: async (_session, error) => {
          errors.push(error);
        },
      },
    }
  );
  const rejection: unknown = await orchestrator.processMessage(session).catch((error: unknown) => error);

  expect({errors, rejection}).toEqual({
    errors: [Object.assign(new Error('hook failure'), {cause: 'hook failure'})],
    rejection: 'hook failure',
  });
});
EOF
 timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --runInBand --runTestsByPath src/orchestration/onErrorCause.test.ts"
